<script setup lang="ts">
import { ref, computed, onMounted, onBeforeUnmount } from 'vue'
import { accountApi as api } from '../accountApi'
import KeyWorker from '../crypto/keygen.worker?worker&inline'
import { preview, GRAM_MASTER, type PublicKeys } from '../crypto/hd.mjs'
const generated=ref<any>(null),savedPhrase=ref(false),generating=ref(false),localPreview=ref<any[]>([])
let keyWorker:Worker|null=null,clearTimer:ReturnType<typeof setTimeout>|null=null
function clearGenerator(){keyWorker?.terminate();keyWorker=null;if(clearTimer)clearTimeout(clearTimer);clearTimer=null;if(generated.value)generated.value.mnemonic='';generated.value=null;savedPhrase.value=false;generating.value=false}
function generate(){clearGenerator();generating.value=true;error.value='';keyWorker=new KeyWorker();keyWorker.onmessage=(e)=>{generating.value=false;if(!e.data.ok){error.value=e.data.error;clearGenerator();return}generated.value=e.data.result;clearTimer=setTimeout(clearGenerator,300000)};keyWorker.onerror=()=>{error.value='Локальная генерация недоступна';clearGenerator()};keyWorker.postMessage({generate:true})}
async function applyKeys(){if(!savedPhrase.value||!generated.value)return;const keys:PublicKeys={...generated.value.keys};Object.assign(config.value,keys);applyMasterPreview();clearGenerator();await save()}
function applyMasterPreview(){const a=preview(config.value)[0];config.value.ton_receiver=a.ton;for(const id of ['usdt_ton','gram'])config.value.networks[id].receiver=a.ton;config.value.networks.trc20.receiver=a.trc20;config.value.networks.bep20.receiver=a.bep20}
function checkKeys(){try{localPreview.value=preview(config.value);applyMasterPreview();error.value=''}catch{error.value='Укажите корректные публичные мастер-ключи';localPreview.value=[]}}
onBeforeUnmount(clearGenerator)

const config=ref<any>(null),orders=ref<any[]>([]),otp=ref(''),error=ref(''),message=ref(''),busy=ref(false),offset=ref(0),total=ref(0)
const treasury=ref<any>(null),treasuryRefreshing=ref(false),treasuryOpen=ref(false),treasuryBusy=ref(false),treasuryMnemonic=ref(''),treasuryProvider=ref('ton'),treasuryMode=ref('consolidate'),treasuryTarget=ref(''),treasuryAmount=ref(''),treasuryPlan=ref<any>(null)
const networks=[{id:'usdt_ton',name:'USDT · TON (Jetton)',hint:'UQ… / EQ…',description:'Официальный master USDT зафиксирован сервером. Укажите адрес владельца, не Jetton-кошелёк.'},{id:'gram',name:'GRAM · TON (Jetton)',hint:'UQ… / EQ…',description:'Укажите выбранный GRAM Jetton master. Символ GRAM сам по себе не идентифицирует токен. Decimals: 9.'},{id:'trc20',name:'USDT · TRON (TRC-20)',hint:'T…',description:'Только USDT контракта TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t. Для каждого нового счёта используется уникальный HD-адрес.'},{id:'bep20',name:'Binance-Peg USDT · BNB Smart Chain',hint:'0x…',description:'Сеть 56. Контракт 0x55d398326f99059ff775485246999027b3197955. Не Tether-native USDT; подтверждение после 20 блоков.'}]
const poolProviders=['ton','usdt_ton','gram','trc20','bep20']
const poolText=ref<Record<string,string>>({})
const prices=computed(()=>{const all=config.value?.prices||[];const canonical=all.filter((p:any)=>['pro_1m','pro_6m','pro_12m'].includes(p.code));return canonical.length?canonical:all})
function title(p:any){return p.days===30?'1 месяц · 30 дней':p.days===180?'6 месяцев · 180 дней':p.days===365?'12 месяцев · 365 дней':p.title}
async function load(){const [c,o]=await Promise.all([api('/admin/billing/settings'),api('/admin/billing/orders?offset='+offset.value)]);c.trc20_xpub||='';c.bep20_xpub||='';c.ton_public_key||='';for(const n of networks){c.networks[n.id]||={receiver:'',master:''}}c.networks.gram.master||=GRAM_MASTER;if(c.treasury_masters){c.ton_receiver=c.treasury_masters.ton||'';for(const id of ['usdt_ton','gram'])c.networks[id].receiver=c.treasury_masters[id]||'';c.networks.trc20.receiver=c.treasury_masters.trc20||'';c.networks.bep20.receiver=c.treasury_masters.bep20||''}for(const id of poolProviders){poolText.value[id]=(c.networks[id]?.address_pool||[]).join('\n')}config.value=c;orders.value=o.items;total.value=o.total;refreshTreasury(false).catch(()=>{})}

async function refreshTreasury(force=true){treasuryRefreshing.value=true;try{treasury.value=await api('/admin/billing/treasury'+(force?'/refresh':''),force?'POST':'GET',force?{}:undefined)}finally{treasuryRefreshing.value=false}}
function treasuryKeys(){return {trc20_xpub:config.value.trc20_xpub,bep20_xpub:config.value.bep20_xpub,ton_public_key:config.value.ton_public_key}}
async function prepareTreasury(){error.value='';try{const {buildTreasuryPlan,decimalToRaw}=await import('../crypto/treasury.mjs');const net=treasury.value.networks.find((n:any)=>n.provider===treasuryProvider.value);let raw=treasuryAmount.value;if(treasuryMode.value==='withdraw'&&raw){const decimals=treasuryProvider.value==='ton'||treasuryProvider.value==='gram'?9:treasuryProvider.value==='bep20'?18:6;raw=decimalToRaw(raw,decimals)}treasuryPlan.value=buildTreasuryPlan({phrase:treasuryMnemonic.value,keys:treasuryKeys(),snapshot:treasury.value,provider:treasuryProvider.value,mode:treasuryMode.value,target:treasuryTarget.value,amountRaw:raw||net?.master_raw})}catch(e:any){error.value=e.message;treasuryPlan.value=null}}
async function runTreasury(){if(!treasuryPlan.value||treasuryBusy.value)return;treasuryBusy.value=true;error.value='';try{const {executeTreasury}=await import('../crypto/treasury.mjs');const input:any={phrase:treasuryMnemonic.value,keys:treasuryKeys(),snapshot:treasury.value,provider:treasuryProvider.value,mode:treasuryMode.value,target:treasuryTarget.value,amountRaw:treasuryPlan.value.actions.at(-1)?.amount_raw||''};await executeTreasury(input);message.value='Операции отправлены и подтверждены в сети.';treasuryMnemonic.value='';treasuryPlan.value=null;await refreshTreasury()}catch(e:any){error.value=e.message}finally{treasuryBusy.value=false}}
function closeTreasury(){treasuryMnemonic.value='';treasuryPlan.value=null;treasuryTarget.value='';treasuryAmount.value='';treasuryOpen.value=false}

async function save(){if(busy.value)return;busy.value=true;error.value='';message.value='';try{for(const id of poolProviders){config.value.networks[id]||={receiver:'',master:''};config.value.networks[id].address_pool=(poolText.value[id]||'').split(/\s+/).filter(Boolean)}await api('/admin/billing/settings','PUT',{trc20_xpub:config.value.trc20_xpub,bep20_xpub:config.value.bep20_xpub,ton_public_key:config.value.ton_public_key,ton_receiver:config.value.ton_receiver,networks:config.value.networks,prices:prices.value.map((p:any)=>({plan_id:p.plan_id,usd:p.usd,ton:p.ton,stars:Number(p.stars),usdt_ton:p.usdt_ton,gram:p.gram,trc20:p.trc20,bep20:p.bep20}))},otp.value);message.value='Реквизиты и цены сохранены. Созданные ранее счета не изменены.';await load()}catch(e:any){error.value=e.message}finally{busy.value=false;otp.value=''}}
onMounted(()=>load().catch(e=>error.value=e.message))
</script>
<template><section class="billing-settings"><header><p class="eyebrow">KINOSOTA · NON-CUSTODIAL CHECKOUT</p><h2>Подписки и приём платежей</h2><p>Три периода PRO, пять крипто-маршрутов и Telegram Stars. Сервер сверяет сеть, контракт, получателя, точную сумму и подтверждение транзакции. Приватные ключи не нужны.</p></header><p v-if="error" role="alert" class="notice error">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><form v-if="config" @submit.prevent="save"><div class="config-note"><strong>Безопасная активация</strong><p>Пустой публичный мастер-ключ или нулевая цена отключают криптоспособ оплаты. Демонстрационные адреса не подставляются в реальные счета. Сохранение требует текущего 2FA-кода.</p></div><h3>Цены · 1 / 6 / 12 месяцев</h3><div class="tariff-grid"><article v-for="p in prices" :key="p.plan_id" class="tariff"><h4>PRO · {{title(p)}}</h4><small>{{p.is_active?'Продажи включены':'Продажи отключены'}}</small><div class="field-grid"><label>USD · витрина<input v-model="p.usd" type="number" min="0" max="1000000" step="0.01" required/></label><label>★ Stars<input v-model="p.stars" type="number" min="0" max="1000000" step="1" required/></label><label>TON<input v-model="p.ton" type="number" min="0" max="1000000" step="0.000000001" required/></label><label>GRAM · Jetton<input v-model="p.gram" type="number" min="0" max="1000000" step="0.000000001" required/></label><label>USDT · TON<input v-model="p.usdt_ton" type="number" min="0" max="1000000" step="0.000001" required/></label><label>USDT · TRC-20<input v-model="p.trc20" type="number" min="0" max="1000000" step="0.000001" required/></label><label>USDT · BEP-20<input v-model="p.bep20" type="number" min="0" max="1000000" step="0.000001" required/></label></div></article></div><p>TON и GRAM: фиксированная цена в монетах, без скрытого обменного курса. HD-счета TRC-20 / BEP-20 сверяются по уникальному адресу и точной цене, без добавочного хвоста суммы.</p><h3>Реквизиты по сетям · HD-деривация</h3><div class="config-note"><p>Каждый новый криптосчёт получает уникальный адрес из PostgreSQL derivation_index. Без публичного мастер-ключа способ оплаты выключен. Старые счета сохраняют свои адреса.</p><button type="button" :disabled="generating" @click="generate">{{generating?'Генерируем локально…':'Сгенерировать мастер-ключи (xpub / TON pubkey) в браузере'}}</button><label>TRC-20 account xpub · m/44'/195'/0'<input v-model="config.trc20_xpub" maxlength="120" autocomplete="off" spellcheck="false" placeholder="xpub…"/></label><label>BEP-20 account xpub · m/44'/60'/0'<input v-model="config.bep20_xpub" maxlength="120" autocomplete="off" spellcheck="false" placeholder="xpub…"/></label><label>TON Public Key · hex/base64<input v-model="config.ton_public_key" maxlength="128" autocomplete="off" spellcheck="false" placeholder="32-byte Ed25519 public key"/></label><button type="button" @click="checkKeys">Проверить первые 3 адреса</button><p>Index #0 автоматически используется как Treasury Hub. Инвойсы начинаются с #1. Подпись консолидации выполняется только локально в браузере; сервер хранит исключительно публичные ключи.</p></div><div v-if="localPreview.length" class="table-scroll"><table><thead><tr><th>Индекс</th><th>TRC-20</th><th>BEP-20</th><th>TON V4R2</th></tr></thead><tbody><tr v-for="a in localPreview" :key="a.index"><td>#{{a.index}}</td><td class="mono">{{a.trc20}}</td><td class="mono">{{a.bep20}}</td><td class="mono">{{a.ton}}</td></tr></tbody></table></div><div class="address-grid"><article class="address-card"><h4>TON · Toncoin</h4><label>Master Treasury Address #0<input v-model="config.ton_receiver" readonly maxlength="80" placeholder="UQ… / EQ…"/></label><p>Сырой формат 0:… нормализуется в mainnet Base64url. Исторические реквизиты; новые счета используют TON Public Key выше.</p></article><article v-for="n in networks" :key="n.id" class="address-card"><h4>{{n.name}}</h4><label>Master Treasury Address #0<input v-model="config.networks[n.id].receiver" readonly maxlength="80" :placeholder="n.hint"/></label><label v-if="n.id==='gram'">GRAM Jetton master<input v-model="config.networks.gram.master" maxlength="80" placeholder="EQ… / UQ…"/></label><p>{{n.description}}</p></article></div><p>Telegram Stars: <strong>{{config.stars_configured?'бот настроен на VPS 1':'бот не настроен'}}</strong>. Секреты бота не передаются на Витрину.</p><p v-if="config.ton_scanner">Проверка сетей: {{config.ton_scanner.error||'нет ошибок последнего цикла'}} · {{config.ton_scanner.last_success_at||'успешных циклов ещё нет'}}</p><div class="save-row"><label>Текущий код 2FA / резервный код<input v-model="otp" autocomplete="one-time-code" maxlength="64" required/></label><button :disabled="busy">{{busy?'Сохраняем…':'Сохранить реквизиты и цены'}}</button><router-link to="/account-security">Безопасность администратора →</router-link></div></form><div v-if="generated" class="key-modal-backdrop"><section class="key-modal" role="dialog" aria-modal="true" aria-label="Локальные мастер-ключи"><h3>Сохраните мнемоническую фразу · 12 слов</h3><p class="notice error">Единственная резервная копия средств! Не отправляйте эту фразу в чат или поддержку. Она не передаётся серверу и не сохраняется в браузере. Окно очистится через 5 минут.</p><p class="mnemonic" data-testid="mnemonic">{{generated.mnemonic}}</p><p>Рецепт восстановления: BIP-39 English, пустая passphrase. TRON m/44'/195'/0'/0/i; BSC m/44'/60'/0'/0/i. TON: BIP-39 → SLIP-0010 Ed25519 m/44'/607'/0', Wallet V4R2, workchain 0, subwallet_id = 698983191 + i. Это НЕ TON-native mnemonic; обычный импорт в TON-кошелёк может дать другой ключ. Сохраните рецепт вместе с фразой и ведите резервную копию индексов счетов.</p><div class="table-scroll"><table><thead><tr><th>Индекс</th><th>TRC-20</th><th>BEP-20</th><th>TON</th></tr></thead><tbody><tr v-for="a in generated.addresses" :key="a.index"><td>#{{a.index}}</td><td class="mono">{{a.trc20}}</td><td class="mono">{{a.bep20}}</td><td class="mono">{{a.ton}}</td></tr></tbody></table></div><label class="ack"><input v-model="savedPhrase" type="checkbox"/>Я сохранил фразу и рецепт восстановления</label><p>После применения будут отправлены только публичные мастер-ключи в составе обычных настроек. Укажите текущий код 2FA ниже. Seed/private key не отправляются.</p><label>Текущий код 2FA / резервный код<input v-model="otp" autocomplete="one-time-code" maxlength="64"/></label><button type="button" :disabled="!savedPhrase||busy||!otp" @click="applyKeys">Применить публичные мастер-ключи</button><button type="button" @click="clearGenerator">Отмена и очистка</button></section></div><h3>Совокупный баланс кассы · Master #0 + адреса #1..N</h3><div v-if="treasury" class="treasury-grid"><article v-for="n in treasury.networks" :key="n.provider" class="treasury-card"><h4>{{n.symbol}} · {{n.provider}}</h4><p><strong>Одноразовые #1..N:</strong> {{n.children}} · {{n.active_count}} адресов</p><p><strong>Master #0:</strong> {{n.master}} <span v-if="n.provider!=='stars'">· газ {{n.master_gas}}</span></p><small class="mono">{{n.master_address}}</small><p v-if="n.error" class="notice error">{{n.error}}</p></article></div><div class="actions"><button type="button" :disabled="treasuryRefreshing" @click="refreshTreasury()">{{treasuryRefreshing?'Обновляем RPC…':'Обновить on-chain балансы'}}</button><button type="button" :disabled="!treasury" @click="treasuryOpen=true">Управление Treasury Hub #0</button></div><div v-if="treasury?.networks.some((n:any)=>n.active.length)" class="table-scroll"><table><thead><tr><th>Сеть / индекс</th><th>Адрес</th><th>Баланс</th><th>Газ</th></tr></thead><tbody><template v-for="n in treasury.networks" :key="n.provider"><tr v-for="a in n.active" :key="n.provider+'-'+a.index"><td>{{n.provider}} #{{a.index}}</td><td class="mono">{{a.address}}</td><td>{{a.amount}} {{n.symbol}}</td><td>{{a.gas}}</td></tr></template></tbody></table></div><div v-if="treasuryOpen" class="key-modal-backdrop"><section class="key-modal" role="dialog" aria-modal="true"><h3>Локальная консоль Treasury Hub</h3><p class="notice error">12 слов используются только в памяти этой вкладки. Они не отправляются серверу и очищаются при закрытии.</p><label>Сеть<select v-model="treasuryProvider"><option v-for="n in treasury.networks.filter((x:any)=>x.provider!=='stars')" :value="n.provider">{{n.provider}} · {{n.symbol}}</option></select></label><label>Операция<select v-model="treasuryMode"><option value="consolidate">Собрать #1..N → Master #0</option><option value="withdraw">Вывести с Master #0</option></select></label><label v-if="treasuryMode==='withdraw'">Внешний адрес<input v-model="treasuryTarget" autocomplete="off"/></label><label v-if="treasuryMode==='withdraw'">Сумма (пусто = весь баланс)<input v-model="treasuryAmount" inputmode="decimal"/></label><label>Мнемоника BIP-39 · 12 слов<input v-model="treasuryMnemonic" type="password" autocomplete="new-password" spellcheck="false"/></label><button type="button" @click="prepareTreasury">Шаг 1 · Проверить и построить план</button><div v-if="treasuryPlan" class="config-note"><strong>{{treasuryPlan.count}} операций</strong><p>Master: <span class="mono">{{treasuryPlan.master}}</span></p><button type="button" :disabled="treasuryBusy" @click="runTreasury">Шаг 2 · Подписать локально и выполнить</button></div><button type="button" @click="closeTreasury">Закрыть и очистить</button></section></div><h3>Все входящие платежи · {{total}}</h3><div class="table-scroll"><table><thead><tr><th>Дата / Пользователь</th><th>Тариф</th><th>Сумма / Сеть</th><th>Статус</th><th>Подтверждение</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td>{{new Date(o.created_at).toLocaleString()}}<small>{{o.user_id}}</small></td><td>{{o.plan_title}} · {{o.duration_days}} дн.</td><td>{{o.amount_display}} {{o.payment?.symbol||o.provider}}<small>{{o.payment?.network}}</small></td><td>{{o.status}}</td><td class="mono">{{o.provider_ref||'—'}}</td></tr><tr v-if="!orders.length"><td colspan="5">После первой подтверждённой оплаты здесь появятся её реквизиты и статус.</td></tr></tbody></table></div><div class="actions" v-if="total>50"><button :disabled="!offset" @click="offset-=50;load()">Назад</button><button :disabled="offset+50>=total" @click="offset+=50;load()">Далее</button></div></section></template>
<style scoped>.key-modal-backdrop{position:fixed;inset:0;background:#050810df;z-index:1000;display:flex;align-items:center;justify-content:center;padding:16px}.key-modal{background:var(--ui-surface);border:1px solid var(--ui-control);border-radius:var(--ui-radius-panel);padding:24px;width:min(1050px,95vw);max-height:85vh;overflow:auto;box-sizing:border-box}.mnemonic{font-size:22px!important;line-height:1.8!important;color:var(--ui-text)!important;background:var(--ui-bg);padding:20px;border:1px solid var(--ui-control);border-radius:var(--ui-radius);user-select:text;overflow-wrap:anywhere}.ack{display:flex!important;align-items:center;gap:12px}.ack input{width:auto!important;min-height:0!important}.key-modal td{max-width:260px;overflow-wrap:anywhere}.billing-settings{padding:28px;background:var(--ui-surface);border:1px solid var(--ui-control);border-radius:var(--ui-radius-panel);color:var(--ui-text);min-width:0;font-size:16px;line-height:1.5}.eyebrow{color:var(--ui-link)!important;font-size:14px;letter-spacing:.1em}.billing-settings h2{font-size:27px;letter-spacing:-.03em;margin:0 0 16px}.billing-settings h3{font-size:20px;margin:32px 0 16px}.billing-settings h4{margin:0 0 8px;font-size:17px}.billing-settings p{color:var(--ui-secondary);font-size:14px;line-height:1.7}.billing-settings small{font-size:14px;color:var(--ui-link)}.billing-settings label{display:block;font-size:14px;color:var(--ui-secondary);margin:14px 0}.billing-settings select{box-sizing:border-box;width:100%;padding:12px;margin-top:8px;background:var(--ui-bg);border:1px solid var(--ui-control);border-radius:var(--ui-radius);color:var(--ui-text);font:inherit;min-height:46px}.billing-settings input{box-sizing:border-box;width:100%;padding:12px;margin-top:8px;background:var(--ui-bg);border:1px solid var(--ui-control);border-radius:var(--ui-radius);color:var(--ui-text);font:inherit;min-height:46px}.billing-settings input:focus{outline:2px solid var(--ui-control);outline-offset:3px}.tariff-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.treasury-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.treasury-card{border:1px solid var(--ui-control);background:var(--ui-bg);border-radius:var(--ui-radius-panel);padding:16px;min-width:0}.tariff,.address-card{border:1px solid var(--ui-control);background:#141b2a80;border-radius:var(--ui-radius-panel);padding:20px;min-width:0}.tariff:nth-child(2){border-color:var(--ui-control);background:var(--ui-surface)}.field-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 12px}.address-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.config-note{padding:18px 20px;background:var(--ui-raised);border:1px solid var(--ui-control);border-radius:var(--ui-radius)}.config-note p{margin-bottom:0}.save-row{display:flex;align-items:end;gap:18px;flex-wrap:wrap;border-top:1px solid var(--ui-control);margin-top:24px;padding-top:14px}.save-row label{flex:1;min-width:200px}.billing-settings button{padding:13px 17px;border:0;border-radius:var(--ui-radius);background:var(--ui-surface);color:var(--ui-on-primary);font:inherit;font-size:14px;font-weight:650;cursor:pointer;min-height:46px;margin-bottom:14px}.billing-settings a{display:inline-block;margin:14px;color:var(--ui-link);font-size:14px}.billing-settings button:disabled{opacity:.5}.table-scroll{overflow:auto}.billing-settings table{width:100%;border-collapse:collapse;font-size:14px;text-align:left}.billing-settings td,.billing-settings th{border-bottom:1px solid var(--ui-control);padding:14px 12px}.billing-settings td small{display:block;margin-top:6px;overflow-wrap:anywhere}.mono{font-family:monospace;max-width:200px;overflow-wrap:anywhere}.actions{display:flex;gap:10px;margin-top:14px}.notice{padding:14px;border-radius:var(--ui-radius);background:var(--ui-raised);color:var(--ui-success)!important}.notice.error{background:var(--ui-raised);color:var(--ui-danger)!important}@media(max-width:1100px){.tariff-grid{grid-template-columns:1fr}.field-grid{grid-template-columns:repeat(4,minmax(0,1fr))}}@media(max-width:650px){.field-grid,.address-grid{grid-template-columns:1fr}.billing-settings{padding:20px}.save-row{display:block}}</style>
